example.code:
/* Escape sequences demo:
   prints a quote and a Windows path two ways. */
#include <iostream>

int main() {
    // \" puts a double quote inside the text
    std::cout << "She said \"hi\"" << '\n';
    // \\ prints a single backslash
    std::cout << "C:\\Users\\guest" << '\n';
    // A raw string keeps every backslash as typed
    std::cout << R"(C:\Users\guest)" << '\n';
    return 0;
}

