practice.solution:
#include <iostream>

int main() {
    // Escaped quotes around the file name
    std::cout << "The file is \"notes.txt\"" << '\n';
    // Escaped backslashes in the path
    std::cout << "D:\\code\\main.cpp" << '\n';
    // A raw string needs no escapes
    std::cout << R"(D:\code\main.cpp)" << '\n';
    return 0;
}
